// ===================== JOURNEY ENCOUNTERS DATA =====================
// Backing data for the Journey tab (see renderJourneyTab/journeyRoll/rollJourneyEncounter/
// applyJourneyApproach in the main file). Split into its own file the same way loot-data.js/
// trap-data.js/puzzle-data.js/npc-data.js/cult-data.js/reference-data.js are — pure content, no
// logic, loaded via a plain <script src> before the main file's own script runs.
//
// Design intent: the DM rolls an encounter whenever they want (once, several times, or not at
// all — there is no auto-roll-once constraint anywhere in the roll engine). Each encounter is a
// small, authored D&D scene, not a random-generation system — enough concrete detail (setting,
// atmosphere, people, and what's actually going on beneath the surface) that a DM can run it
// cold, plus several distinct player approaches that each lead somewhere different. Reuses the
// project's own existing systems for consequences instead of inventing new ones (see
// applyJourneyConsequence in the main file) and reuses existing Trap/Hazard/Puzzle/NPC content
// via sourceRef instead of duplicating it here.
//
// One shape:
//   {
//     id: "unique-slug",
//     category: "nothing"|"peaceful"|"hostile"|"weather"|"strange"|"divine"|"hazard"|"discovery",
//       // reuses JOURNEY_CATEGORY_DEFS from the main file as-is — same 8 categories, same
//       // per-setting weighting (JOURNEY_SETTINGS), just a richer payload per entry now.
//     settings: ["countryside","forest",...] | ["any"],
//       // which JOURNEY_SETTINGS.key values this can roll under. 'any' means it can come up
//       // regardless of the currently selected travel setting (used sparingly, for genuinely
//       // setting-agnostic scenes — a lone traveler, an NPC encounter, etc.)
//     title: "A short scene title",
//     scene: { environment: "terrain/weather/light/sound/smell — the physical scene",
//               atmosphere: "the vibe/feel — what makes this moment memorable" },
//     people: [ { name, appearance, personality, wants, knows, hides, npcId } ],
//       // 0+ entries. npcId is optional — set it when this person IS a real NPC_LIBRARY entry
//       // (see sourceRef below for the matching {type:'npc', ref:npcId} on the encounter).
//     situation: "DM-only ground truth of what's actually going on — not read aloud verbatim",
//     approaches: [
//       { label: "Help him", outcome: "narrated result text the DM reads/paraphrases after the
//                                       table picks this",
//         consequence: { type: "loot"|"namedItem"|"gold"|"monster"|"namedNpc"|"buff"|"debuff"|"note"|"none", ...fields } },
//       // 3-5 per encounter. consequence.type fields:
//       //   loot: {rarity}                         namedItem: {itemName, rarity}
//       //   gold: {amount}  (negative = a cost)     monster: {crBand:[lo,hi]}
//       //   namedNpc: {npcName}  (exact monsterDatabase/NPC_LIBRARY_MONSTERS name)
//       //   buff/debuff: {text, durationMs}         note: no fields — text-only outcome
//       //   none: no fields — pure flavor, nothing happens
//     ],
//     sourceRef: { type: "trap"|"hazard"|"puzzle"|"npc", ref: "exact name/id" }, // optional
//       // Resolved LIVE at render/apply time by journeySourceContent() in the main file —
//       // never duplicate the source content itself into this file.
//   }

